def icon(name):
    d={
      'arrow':'<path d="M4 12h15m-6-6 6 6-6 6"/>',
      'down':'<path d="M12 3v17m-6-6 6 6 6-6"/>',
      'external':'<path d="M14 4h6v6m0-6-9 9"/><path d="M20 13v6a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h6"/>',
      'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
      'menu':'<path d="M4 7h16M4 12h16M4 17h16"/>',
    }[name]
    return f'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{d}</svg>'

def nav(current,prefix=''):
    sections=[('Home','index.html','home'),('Projects','projects.html','projects'),('Research','research.html','research'),('Teaching','teaching.html','teaching'),('About','about.html','about')]
    links=''.join(f'<a href="{prefix}{url}"'+(' aria-current="page"' if current==key else '')+f'>{label}</a>' for label,url,key in sections)
    return f'''<header class="site-header"><div class="shell nav-inner">
      <a class="brand" href="{prefix}index.html" aria-label="Mikhail Baltushkin, home"><span class="brand-glyph">mb.</span><span>Mikhail<span class="dot">.</span> Baltushkin</span></a>
      <nav id="main-nav" class="nav-links" aria-label="Main navigation" data-open="false">{links}</nav>
      <div class="nav-actions"><button type="button" class="icon-button" data-theme-toggle aria-label="Switch to light theme">{icon('sun')}</button><button type="button" class="icon-button mobile-toggle" data-menu-toggle aria-label="Toggle navigation" aria-expanded="false" aria-controls="main-nav">{icon('menu')}</button></div>
      </div></header>'''

def footer(prefix=''):
    return f'''<footer class="site-footer"><div class="shell"><div class="footer-main"><div><a class="brand" href="{prefix}index.html"><span class="brand-glyph">mb.</span><span>Mikhail<span class="dot">.</span> Baltushkin</span></a><p>Research in mathematics. Work in scientific computing.</p></div><div class="footer-links"><a href="mailto:{EMAIL}">Email</a><a href="{GITHUB}" target="_blank" rel="noopener noreferrer">GitHub</a><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn</a><a href="{prefix}assets/docs/cv.pdf">CV ↗</a></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> Mikhail Baltushkin. Built with curiosity, mathematics & code.</span><span><span class="status-pulse"></span> Raleigh, North Carolina · NC State University</span></div></div></footer>'''

def page(name,title,description,content,prefix='',og='assets/images/social-card.svg'):
    path=ROOT/name
    path.parent.mkdir(exist_ok=True,parents=True)
    url=BASE+name.replace('index.html','')
    html=f'''<!doctype html>
<html lang="en" data-theme="dark"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)} | Mikhail Baltushkin</title>
<meta name="description" content="{escape(description,quote=True)}">
<meta name="author" content="Mikhail Baltushkin"><meta name="theme-color" content="#080d18">
<meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | Mikhail Baltushkin">
<meta property="og:description" content="{escape(description,quote=True)}">
<meta property="og:image" content="{BASE}{og}"><meta property="og:url" content="{url}">
<meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="{url}">
<link rel="icon" href="{prefix}assets/images/favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="{prefix}assets/css/styles.css">
<script src="{prefix}assets/js/site.js" defer></script>
</head><body><a class="skip-link" href="#main">Skip to content</a><div class="bg-atmosphere" aria-hidden="true"></div><div class="ambient-blob" aria-hidden="true"></div>{nav({'index.html':'home','projects.html':'projects','research.html':'research','teaching.html':'teaching','about.html':'about'}.get(name,'projects'),prefix)}
<main id="main">{content}</main>{footer(prefix)}</body></html>'''
    path.write_text(html,encoding='utf-8')

def heading(kicker,title,desc=None,compact=False):
    return f'''<section class="page-intro {'compact' if compact else ''}"><div class="shell"><p class="eyebrow"><span class="signal"></span>{kicker}</p><h1>{title}</h1>{f'<p>{desc}</p>' if desc else ''}</div></section>'''

def taglist(*tags):return '<div class="tag-row">'+''.join(f'<span class="tag">{t}</span>' for t in tags)+'</div>'

def art_tda():
    # Stylized persistence features; illustrative, not thesis plots.
    circles=''.join(f'<circle cx="{x}" cy="{y}" r="{r}" fill="none" stroke="{c}" stroke-width="1.3" opacity=".7"/>' for x,y,r,c in [(112,98,42,'#83e2e4'),(112,98,29,'#83e2e4'),(112,98,14,'#b6a6ff'),(205,125,53,'#988efa'),(205,125,37,'#988efa'),(205,125,23,'#83e2e4'),(278,73,34,'#79d9de')])
    pts=''.join(f'<circle cx="{x}" cy="{y}" r="2.4" fill="#84e3e5" opacity=".8"/>' for x,y in [(58,61),(79,142),(125,57),(155,165),(207,70),(252,124),(308,146),(304,57),(171,43)])
    return f'<svg viewBox="0 0 360 193" aria-hidden="true" preserveAspectRatio="xMidYMid slice"><defs><pattern id="pat-tda" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#8ce5e7" stroke-opacity=".08"/></pattern></defs><rect width="360" height="193" fill="url(#pat-tda)"/>{circles}{pts}<path d="M20 163Q109 65 179 140T338 34" stroke="#b2a8ff" opacity=".3" fill="none" stroke-width="2"/></svg>'

def art_pendulum():
    arcs=''.join(f'<path d="M{150-r} 95 A{r} {r} 0 0 1 {150+r} 95" fill="none" stroke="#a99cff" stroke-width="1" stroke-opacity="{.08+i*.055}"/>' for i,r in enumerate(range(43,144,20)))
    return f'<svg viewBox="0 0 360 193" aria-hidden="true" preserveAspectRatio="xMidYMid"><path d="M0 20h360M0 55h360M0 90h360M0 125h360M0 160h360" stroke="#9b93c2" stroke-opacity=".07"/>{arcs}<path d="M152 32L219 109L280 150" stroke="#c2c4ff" stroke-width="3.2" stroke-linecap="round"/><circle cx="152" cy="32" r="5" fill="#d1ffff"/><circle cx="219" cy="109" r="11" fill="#89e4df"/><circle cx="280" cy="150" r="12" fill="#a798ff"/><path d="M186 40C124 107 193 190 324 131" stroke="#71dddd" stroke-width="2" stroke-dasharray="4 5" opacity=".75" fill="none"/></svg>'

def art_game():
    nodes=[(70,99),(151,49),(152,149),(246,55),(251,147),(317,104)]
    lines=[(0,1),(0,2),(1,3),(1,4),(2,4),(3,5),(4,5)]
    s=''.join(f'<path d="M{nodes[a][0]} {nodes[a][1]}L{nodes[b][0]} {nodes[b][1]}" stroke="#8b9fe0" stroke-width="1.6" opacity=".62"/>' for a,b in lines)
    s+=''.join(f'<circle cx="{x}" cy="{y}" r="{11 if i in (0,5) else 8}" fill="{c}" stroke="#bec5ff" stroke-width="1.5"/>' for i,(x,y) in enumerate(nodes) for c in ['#2d365c' if i not in (0,5) else '#4f597e'])
    return '<svg viewBox="0 0 360 193" aria-hidden="true">'+s+'<circle cx="70" cy="99" r="4" fill="#82e2dc"/><circle cx="317" cy="104" r="4" fill="#ada1ff"/></svg>'

def feature(kind,eyebrow,title,summary,href,tags,ext=None):
    art={'tda':art_tda,'pendulum':art_pendulum,'games':art_game}[kind]()
    footerlink=f'<a href="{href}">Explore project ↗</a>'
